#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Ridgeline HR Agent: Render service + CI deploy (HANDOFF step 3, SPEC slice 1).
# Run from the repo root: scripts/setup_render.sh [--from N]   (N = the stage to resume at)
# It writes only non-secret values and EVAL_BYPASS_KEY to the gitignored .env, never LLM_API_KEY.

FROM=1
if [[ "${1:-}" == "--from" ]]; then FROM="${2:-1}"; fi
# want N: true if stage N should run; when resuming, earlier stages are skipped but still counted.
want() { if (( FROM > $1 )); then _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 1; fi; }
copy() { if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy; note "(copied to the clipboard)"; fi; }
REPO=i2oss/hr-agent

TOTAL_STAGES=8

banner "Ridgeline HR Agent · Render + CI deploy"

if want 1; then
stage "Pre-flight: which branch Render deploys"
[[ -f Dockerfile && -f .github/workflows/ci.yml ]] || { warn "Run this from the hr-agent repo root (Dockerfile and ci.yml not found)."; exit 1; }
command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 || warn "gh isn't logged in: stages 6 and 8 need it (run: gh auth login)."
if gh api "repos/$REPO/contents/Dockerfile?ref=main" >/dev/null 2>&1; then
  say "main already has the Dockerfile and ci.yml (PR #28 is merged): deploy main."
  RENDER_BRANCH=main
else
  say "main doesn't have the app yet: PR #28 (worktree-implement-spec) isn't merged."
  step "Option A: merge PR #28 on GitHub first, then re-run this wizard. Render deploys main and"
  note "  CI's deploy job (main only) drives every deploy. Required for stage 8's proof."
  step "Option B: deploy the branch worktree-implement-spec now with manual deploys, and switch"
  note "  Render's branch to main after the merge (Settings → Build & Deploy → Branch)."
  ask RENDER_BRANCH "Branch for Render (main / worktree-implement-spec):"
fi
write_env RENDER_BRANCH "$RENDER_BRANCH"
pause
fi

if want 2; then
stage "Keys: an Anthropic key for Render, and EVAL_BYPASS_KEY"
say "Use a separate Anthropic key for Render, so you can revoke it without touching your local one."
open_url "https://console.anthropic.com/settings/keys"
step "Create key → name it 'hr-agent-render' → copy it. You'll paste it into Render in stage 4."
note "Not saved anywhere by this wizard. Also check Billing: credit and the monthly spend limit (SPEC §3.2, LLM budget)."
pause "Press Enter once the key is copied somewhere safe (or paste it into Render straight away in stage 4)"
EVAL_BYPASS_KEY=$(_existing EVAL_BYPASS_KEY || true)
# An old-template .env has "EVAL_BYPASS_KEY=   # secret; …": a comment, not a key.
if [[ ! "$EVAL_BYPASS_KEY" =~ ^[A-Za-z0-9_-]{16,}$ ]]; then EVAL_BYPASS_KEY=$(openssl rand -hex 24); fi
write_env EVAL_BYPASS_KEY "$EVAL_BYPASS_KEY"
note "EVAL_BYPASS_KEY lets the deployed latency run and the demo runner skip the rate limits."
note "For evaluation.run, export it in your shell first: export EVAL_BYPASS_KEY=\$(grep ^EVAL_BYPASS_KEY= .env | cut -d= -f2)"
pause
fi

if want 3; then
stage "Render: create the web service"
open_url "https://dashboard.render.com/web/new"
step "New → Web Service → Git provider: GitHub → pick $REPO."
note "  If it isn't listed: 'Configure GitHub' and give the Render app access to that repository."
step "Name: ridgeline-hr-agent (it becomes the URL: https://ridgeline-hr-agent.onrender.com, if free)."
step "Language / Runtime: Docker.   Branch: $(_existing RENDER_BRANCH || echo main).   Root directory: blank."
step "Region: the one nearest you.   Instance type: Free (512 MB, 0.1 CPU)."
step "Dockerfile path: ./Dockerfile.   Docker command: blank (the Dockerfile's CMD reads \$PORT)."
note "Don't press Create yet: environment variables and Advanced settings come next."
pause
fi

if want 4; then
stage "Render: environment variables, health check, auto-deploy"
ask DAILY_MESSAGE_CAP_RENDER "DAILY_MESSAGE_CAP for production (Enter for 100, the spec default):"
DAILY_MESSAGE_CAP_RENDER=${DAILY_MESSAGE_CAP_RENDER:-100}
write_env DAILY_MESSAGE_CAP_RENDER "$DAILY_MESSAGE_CAP_RENDER"
ENV_BLOCK="LLM_PROVIDER=anthropic
LLM_MODEL=claude-sonnet-5-5
JUDGE_MODEL=claude-sonnet-5-5
EMBEDDINGS_PROVIDER=local
RETRIEVAL_TOP_K=5
RETRIEVAL_MODE=hybrid
DEMO_TODAY=2026-11-02
RATE_LIMITS_ENABLED=true
RATE_LIMIT_PER_IP=20
MAX_MESSAGE_CHARS=2000
MAX_TURNS_PER_SESSION=30
DAILY_MESSAGE_CAP=$DAILY_MESSAGE_CAP_RENDER"
step "Environment Variables → 'Add from .env' and paste this block (or add each row by hand):"
printf '%s\n' "$ENV_BLOCK" | sed 's/^/      /'
copy "$ENV_BLOCK"
step "Add two more rows by hand, as secrets: LLM_API_KEY = the key from stage 2;"
step "  EVAL_BYPASS_KEY = the value in .env (copy it with: grep ^EVAL_BYPASS_KEY= .env | cut -d= -f2 | pbcopy)."
note "Leave out PORT (Render sets it), MCP_POLICY_URL / MCP_HR_URL, LLM_BASE_URL, VOYAGE_API_KEY and"
note "EVIDENCE_THRESHOLD: their defaults are right. RENDER_GIT_COMMIT is set by Render; /health reports it."
step "Advanced → Health Check Path: /health"
step "Advanced → Auto-Deploy: Off (or 'No'). If the form doesn't offer it, set it right after creation:"
note "  Settings → Build & Deploy → Auto-Deploy → Off. CI's deploy hook is the only deploy trigger."
step "Create Web Service. The first build takes several minutes (it bakes the embedding model)."
pause "Press Enter once you've clicked Create"
fi

if want 5; then
stage "First deploy: URL and /health"
step "On the service page, copy the URL at the top (https://….onrender.com)."
ask APP_URL "Paste the service URL:"
APP_URL=${APP_URL%/}
write_env APP_URL "$APP_URL"
say "Polling $APP_URL/health until the deploy is live (up to ~10 min; Ctrl-C to stop) …"
ok=""
for _ in $(seq 1 60); do
  if body=$(curl -fsS --max-time 30 "$APP_URL/health" 2>/dev/null); then ok=1; break; fi
  sleep 10
done
if [[ -n "$ok" ]]; then
  printf '%s' "$body" | python3 -c '
import json, sys
h = json.load(sys.stdin)
tools = sum(len(v.get("tools", [])) for v in h["mcp"].values())
print("  status:", h["status"], "| version:", h["version"] or "(empty!)", "| tools:", tools, "| llm:", h["llm"]["model"], "| demo_today:", h["demo_today"])
if not h["version"]: print("  ⚠ version is empty: CI waits for the git SHA here, so tell Claude.")
if tools != 9: print("  ⚠ expected 9 tools")'
  note "Check the service's Metrics tab later: memory should sit near 230–240 MiB (measured locally)."
else
  warn "No healthy /health yet. Check the Render Logs tab; re-run with --from 5 when it's up."
fi
pause
fi

if want 6; then
stage "GitHub: deploy hook secret and APP_URL variable"
step "Render → the service → Settings → Deploy Hook → copy the URL (https://api.render.com/deploy/srv-…?key=…)."
ask_secret RENDER_DEPLOY_HOOK_URL "Paste the deploy hook URL (hidden):"
# Hidden input hides a failed paste too; an empty secret makes CI run curl -X POST "".
while [[ "$RENDER_DEPLOY_HOOK_URL" != https://api.render.com/deploy/* ]]; do
  warn "That doesn't look like a deploy hook URL (https://api.render.com/deploy/srv-…). Try again."
  ask_secret RENDER_DEPLOY_HOOK_URL "Paste the deploy hook URL (hidden):"
done
if confirm "Set GitHub secret RENDER_DEPLOY_HOOK_URL and variable APP_URL=$(_existing APP_URL) on $REPO?"; then
  set_secret RENDER_DEPLOY_HOOK_URL "$RENDER_DEPLOY_HOOK_URL"
  set_var APP_URL "$(_existing APP_URL)"
else
  SKIPPED+=("GitHub secret RENDER_DEPLOY_HOOK_URL and variable APP_URL")
fi
note "The hook URL isn't written to .env: anyone holding it can trigger deploys."
pause
fi

if want 7; then
stage "Live smoke: one real question (~\$0.04)"
APP_URL=$(_existing APP_URL)
say "The same check as CI's post-deploy smoke: Maya (E1001) asks about PTO carryover."
if confirm "Send it to $APP_URL/chat?"; then
  curl -fsS --max-time 180 -X POST "$APP_URL/chat" -H 'content-type: application/json' \
    -d "{\"session_id\":\"wizard-smoke-$(date +%s)\",\"speaking_as\":\"E1001\",\"message\":\"How many unused PTO days can I carry over?\"}" \
  | python3 -c '
import json, sys
a = json.load(sys.stdin)["answer"]
cites = sorted({c["doc_id"] + " §" + c["section"] for f in a["policy_facts"] for c in f["citations"]})
print("  lead:", a["lead"]); print("  citations:", ", ".join(cites) or "(none)")
print("  ✓ smoke ok" if any(c.startswith("RSE-PTO-01") for c in cites) else "  ⚠ no RSE-PTO-01 citation")' \
  || warn "The request failed: check Render Logs (a cold start can take a minute; retry with --from 7)."
fi
pause
fi

if want 8; then
stage "Prove that a failing test blocks the deploy"
if [[ "$(_existing RENDER_BRANCH || echo main)" != "main" ]] || ! gh api "repos/$REPO/contents/.github/workflows/ci.yml?ref=main" >/dev/null 2>&1; then
  warn "Not possible yet: CI deploys only on a push to main, and main doesn't run this pipeline."
  note "After merging PR #28: Render → Settings → Branch → main, then: scripts/setup_render.sh --from 8"
  SKIPPED+=("failing-test proof (stage 8): needs PR #28 merged and Render on main")
else
  APP_URL=$(_existing APP_URL)
  say "Plan: push a commit to main that adds one deliberately failing test, see the run fail with"
  say "'deploy' skipped and /health unchanged, then revert it. The revert's run deploys for real"
  say "(one post-deploy smoke, ~\$0.04). Both run URLs are saved to .env for deployed.md."
  before=$(curl -fsS --max-time 60 "$APP_URL/health" | python3 -c 'import json,sys; print(json.load(sys.stdin)["version"])' || echo "?")
  note "Live version now: $before"
  if confirm "Push the failing-test commit to main?"; then
    tmp=$(mktemp -d); git fetch -q origin main; git worktree add -q "$tmp" origin/main
    printf 'def test_ci_gate_proof():\n    raise AssertionError("deliberate: proves a failing test blocks the deploy")\n' > "$tmp/tests/test_ci_gate_proof.py"
    git -C "$tmp" add tests/test_ci_gate_proof.py
    git -C "$tmp" commit -qm "CI gate proof: a deliberately failing test (reverted next)"
    git -C "$tmp" push -q origin HEAD:main
    red=$(git -C "$tmp" rev-parse HEAD)
    run_for() { local id=""; for _ in $(seq 1 30); do id=$(gh run list -R "$REPO" --commit "$1" --workflow ci --json databaseId --jq '.[0].databaseId'); [[ -n "$id" ]] && break; sleep 5; done; printf '%s' "$id"; }
    rid=$(run_for "$red"); say "Watching run $rid …"; gh run watch -R "$REPO" "$rid" >/dev/null 2>&1 || true
    gh run view -R "$REPO" "$rid" --json jobs --jq '.jobs[] | "  \(.name): \(.conclusion)"'
    after=$(curl -fsS --max-time 60 "$APP_URL/health" | python3 -c 'import json,sys; print(json.load(sys.stdin)["version"])' || echo "?")
    note "Live version after: $after (should equal $before)"
    write_env CI_PROOF_RED_RUN "https://github.com/$REPO/actions/runs/$rid"
    step "Also check Render → Events: no new deploy since the push."
    pause "Press Enter to revert (this push deploys)"
    git -C "$tmp" revert --no-edit HEAD >/dev/null; git -C "$tmp" push -q origin HEAD:main
    green=$(git -C "$tmp" rev-parse HEAD)
    gid=$(run_for "$green"); say "Watching run $gid (test → deploy → smoke) …"; gh run watch -R "$REPO" "$gid" >/dev/null 2>&1 || true
    gh run view -R "$REPO" "$gid" --json jobs --jq '.jobs[] | "  \(.name): \(.conclusion)"'
    write_env CI_PROOF_GREEN_RUN "https://github.com/$REPO/actions/runs/$gid"
    git worktree remove --force "$tmp"
  else
    SKIPPED+=("failing-test proof (stage 8)")
  fi
fi
pause
fi

finish
say "Next: tell Claude the results (the APP_URL, the /health line and the stage 8 run URLs in .env)."
